import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"algorithm Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"algorithm","tag":"algorithm","title":"algorithm Tag","prev":null,"next":null,"posts":[{"title":"简单多边形的判定","url":"/posts/2020-08-09-simple-polygon/","date":"2020-08-09 14:50","tags":["algorithm"],"html":"<p>在实际工作中，需要在照片上选定一个范围，这个范围是个多边形，并且是个简单多边形，我们需要判定是否是个合法的简单多边形，主要判定的是任意两边不能交叉。</p>\\n<h2 id=\\"判断两条线段相交\\" tabindex=\\"-1\\">判断两条线段相交 <a class=\\"header-anchor\\" href=\\"#判断两条线段相交\\" aria-label=\\"Permalink to &quot;判断两条线段相交&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们可以借助向量的知识来判断两个线段是否相交。二维向量的叉乘(cross product)的几何意义是以两向量为邻边的平行四边形的面积。此外，定义两个向量 a, b。\\n当 <code>aXb &lt; 0</code>, b 对应的线段，在 a 的顺时针方向。当 <code>aXb = 0</code>时， a 与 b 共线。当 <code>aXb &gt; 0</code>，b 在 a 的逆时针方向。\\n如果两条线段相交，那必然一条线段的终点和起点，在另外一条线段的两侧。</p>\\n<h2 id=\\"判断多边形两边是否相交\\" tabindex=\\"-1\\">判断多边形两边是否相交 <a class=\\"header-anchor\\" href=\\"#判断多边形两边是否相交\\" aria-label=\\"Permalink to &quot;判断多边形两边是否相交&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>简单并且暴力的方法是检测任意两边是否有交点，在复杂度不高的情况下可以使用这种方法。但是显然是有更优解的，目前比较有名的两个算法是 <code>The Bentley-Ottmann Algorithm</code> 和\\n<code>The Shamos-Hoey Algorithm</code>。算法的细节请查看下方的参考，我就不详细描述了。</p>\\n<h2 id=\\"简单多边形判定的实现\\" tabindex=\\"-1\\">简单多边形判定的实现 <a class=\\"header-anchor\\" href=\\"#简单多边形判定的实现\\" aria-label=\\"Permalink to &quot;简单多边形判定的实现&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> interface</span><span style=\\"color:#6F42C1\\"> Point</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  x</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  y</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> interface</span><span style=\\"color:#6F42C1\\"> Line</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  start</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Point</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  end</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Point</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> samePoint</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">p1</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Point</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">p2</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Point</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (p1.x </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#24292E\\"> p2.x </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#24292E\\"> p1.y </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#24292E\\"> p2.y) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  } </span><span style=\\"color:#D73A49\\">else</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> signedArea</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">p1</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Point</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">p2</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Point</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">p3</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Point</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> (p1.x </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#24292E\\"> p3.x) </span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#24292E\\"> (p2.y </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#24292E\\"> p3.y) </span><span style=\\"color:#D73A49\\">></span><span style=\\"color:#24292E\\"> (p2.x </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#24292E\\"> p3.x) </span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#24292E\\"> (p1.y </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#24292E\\"> p3.y);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> intersectLine</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">l1</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Line</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">l2</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Line</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // consecutive edge return false</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    samePoint</span><span style=\\"color:#24292E\\">(l1.start, l2.start) </span><span style=\\"color:#D73A49\\">||</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    samePoint</span><span style=\\"color:#24292E\\">(l1.start, l2.end) </span><span style=\\"color:#D73A49\\">||</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    samePoint</span><span style=\\"color:#24292E\\">(l1.end, l2.start) </span><span style=\\"color:#D73A49\\">||</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    samePoint</span><span style=\\"color:#24292E\\">(l1.end, l2.end)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  ) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> (</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    signedArea</span><span style=\\"color:#24292E\\">(l1.start, l2.start, l2.end) </span><span style=\\"color:#D73A49\\">!==</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      signedArea</span><span style=\\"color:#24292E\\">(l1.end, l2.start, l2.end) </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    signedArea</span><span style=\\"color:#24292E\\">(l1.start, l1.end, l2.start) </span><span style=\\"color:#D73A49\\">!==</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      signedArea</span><span style=\\"color:#24292E\\">(l1.start, l1.end, l2.end)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#6F42C1\\"> intersectPolygon</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">points</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Array</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">Point</span><span style=\\"color:#24292E\\">>) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> len</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> points.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  for</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">let</span><span style=\\"color:#24292E\\"> i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> len </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#005CC5\\"> 1</span><span style=\\"color:#24292E\\">; i</span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    for</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">let</span><span style=\\"color:#24292E\\"> j </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> i </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#005CC5\\"> 1</span><span style=\\"color:#24292E\\">; j </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> len; j</span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      const</span><span style=\\"color:#005CC5\\"> l1</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Line</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        start: points[i],</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        end: points[(i </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#005CC5\\"> 1</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">%</span><span style=\\"color:#24292E\\"> len]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      const</span><span style=\\"color:#005CC5\\"> l2</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Line</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        start: points[j],</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        end: points[(j </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#005CC5\\"> 1</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">%</span><span style=\\"color:#24292E\\"> len]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      };</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">intersectLine</span><span style=\\"color:#24292E\\">(l1, l2)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br><span class=\\"line-number\\">51</span><br><span class=\\"line-number\\">52</span><br><span class=\\"line-number\\">53</span><br><span class=\\"line-number\\">54</span><br><span class=\\"line-number\\">55</span><br><span class=\\"line-number\\">56</span><br><span class=\\"line-number\\">57</span><br><span class=\\"line-number\\">58</span><br><span class=\\"line-number\\">59</span><br><span class=\\"line-number\\">60</span><br><span class=\\"line-number\\">61</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>简单多边形判定的本质是任意两边是否相交，如果是邻边的话就直接跳过。在复杂度不高的情况下，可以直接使用遍历的方法来实现。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"http://geomalgorithms.com/a09-_intersect-3.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">Intersections of a Set of Segments</a></p>\\n<p><a href=\\"https://bryceboe.com/2006/10/23/line-segment-intersection-algorithm/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Line Segment Intersection Algorithm</a></p>\\n<p><a href=\\"https://github.com/rowanwins/shamos-hoey\\" target=\\"_blank\\" rel=\\"noreferrer\\">shamos-hoey</a></p>\\n"},{"title":"使用最小费用最大流模型解决酒店管理收益最大化问题","url":"/posts/2015-12-29-minimum-cost-flow-problem/","date":"2015-12-29 11:15","tags":["algorithm"],"html":"<p>最近老师布置个作业,很没有头绪,于是各种咨询,大家的解决方案是使用最小费用最大流模型来求解,于是我便花了 3 天时间来理解这个算法.</p>\\n<h2 id=\\"问题描述\\" tabindex=\\"-1\\">问题描述 <a class=\\"header-anchor\\" href=\\"#问题描述\\" aria-label=\\"Permalink to &quot;问题描述&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>问题很简单,你有一个只有 5 个房间的酒店,然后本周会有 18 个订单到来,怎样接受订单可以使本周的收益达到最大值.也就是把这 18 个订单填写到一个 5*7 的表格里\\n怎么填收益最大,订单要么接受要么拒绝,也可以说是典型的 01 背包问题吧,但用动态规划不好抽象出来状态转移方程,所以我还是选择用最大流来做.每个订单包含 3 个信息:每晚付的房费,从周几开始入住,入住几天.</p>\\n<h2 id=\\"抽象数据模型\\" tabindex=\\"-1\\">抽象数据模型 <a class=\\"header-anchor\\" href=\\"#抽象数据模型\\" aria-label=\\"Permalink to &quot;抽象数据模型&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>因为题目要求是球最大收益,而流模型是最小费用,所以我们把收益取相反数即可.关键是建立容量和权值,因为房间的数量是 5,所以限制源点和汇点的容量是 5,权值是 0.然后中间设置 8 个点,产生 7 条边,每条边代表每天的流,权值为 0,容量为无穷大.这里我们不能简单的连接点来设置订单的边,因为有相同的起始日期和结束日期的订单.这样会造成冲突,如何解决冲突呢? 我们可以在订单的边上再加一个顶点来进行区分.模型图如下所示:\\n<img src=\\"/assets/model.png\\" alt=\\"model\\" loading=\\"lazy\\">\\n顶点 11 和顶点 16 是重复边的订单,对应的是第一个订单和第 6 个订单.源码和输入数据可以在文章末尾看到.</p>\\n<h2 id=\\"查找增广路径\\" tabindex=\\"-1\\">查找增广路径 <a class=\\"header-anchor\\" href=\\"#查找增广路径\\" aria-label=\\"Permalink to &quot;查找增广路径&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>这里我们使用<a href=\\"https://en.wikipedia.org/wiki/Ford%E2%80%93Fulkerson_algorithm\\" target=\\"_blank\\" rel=\\"noreferrer\\">Ford–Fulkerson</a>算法来计算每次的增广路径.</p>\\n<h2 id=\\"路径的查找\\" tabindex=\\"-1\\">路径的查找 <a class=\\"header-anchor\\" href=\\"#路径的查找\\" aria-label=\\"Permalink to &quot;路径的查找&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>每次增广路径的查找都需要得到最小权值的路径.查找路径使用的是<a href=\\"https://en.wikipedia.org/wiki/Shortest_Path_Faster_Algorithm\\" target=\\"_blank\\" rel=\\"noreferrer\\">SPFA</a>算法.</p>\\n<h2 id=\\"第一次查找增广路径\\" tabindex=\\"-1\\">第一次查找增广路径 <a class=\\"header-anchor\\" href=\\"#第一次查找增广路径\\" aria-label=\\"Permalink to &quot;第一次查找增广路径&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><img src=\\"/assets/hotel1_1.png\\" alt=\\"hotel1_1\\" loading=\\"lazy\\"></p>\\n<h2 id=\\"第二次查找增广路径\\" tabindex=\\"-1\\">第二次查找增广路径 <a class=\\"header-anchor\\" href=\\"#第二次查找增广路径\\" aria-label=\\"Permalink to &quot;第二次查找增广路径&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><img src=\\"/assets/hotel1_2.png\\" alt=\\"hotel1_2\\" loading=\\"lazy\\"></p>\\n<p>以此类推求出最后的结果~</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考: <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考:&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://github.com/acgotaku/USTC-Coding/tree/master/hotel\\" target=\\"_blank\\" rel=\\"noreferrer\\">Source code</a></p>\\n<p><a href=\\"http://www.cnblogs.com/gaochundong/p/ford_fulkerson_maximum_flow_algorithm.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">Ford–Fulkerson</a></p>\\n"}]},"relativePath":"tags/algorithm/index.md","filePath":"tags/[slug].md"}'),l={name:"tags/algorithm/index.md"};function p(e,o,r,t,c,i){return n(),a("div")}const m=s(l,[["render",p]]);export{b as __pageData,m as default};
